using UnityEditor;
using UnityEngine;

namespace Illusion.Rendering.Editor
{
    internal static class PathTracingInlineKernels
    {
        internal const string ValidationPath = PathTracingInlineGenerator.OutputFolder + "/PathTracingInlineValidation.compute";

        private const string Header =
            "// Generated by IllusionRP. Do not edit.\n" +
            "#pragma only_renderers d3d11\n" +
            "#pragma use_dxc\n" +
            "#pragma require inlineraytracing\n";

        internal const string TableInclude = "#include \"Packages/com.kurisu.illusion-render-pipelines/ShaderLibrary/PathTracing/Inline/PathTracingInlineTable.hlsl\"\n";

        public static void Write(PathTracingInlineRegistry registry)
        {
            string validation = Header +
                "#pragma kernel PathTracingInlineValidate\n" +
                "#pragma kernel PathTracingInlineValidationCompare\n" +
                "#include \"" + PathTracingInlineGenerator.EvaluatorsPath + "\"\n" +
                "#include \"Packages/com.kurisu.illusion-render-pipelines/ShaderLibrary/PathTracing/Inline/PathTracingInlineValidation.hlsl\"\n" +
                TableInclude;
            if (PathTracingInlineGenerator.WriteIfChanged(ValidationPath, validation))
                AssetDatabase.ImportAsset(ValidationPath);

            var shader = AssetDatabase.LoadAssetAtPath<ComputeShader>(ValidationPath);
            if (registry && registry.Validation != shader)
            {
                registry.Validation = shader;
                EditorUtility.SetDirty(registry);
                AssetDatabase.SaveAssetIfDirty(registry);
            }
        }
    }
}
